// chrome-extension-release task: store-release — the pack-contributed release
// trigger (per-project-scheduling DESIGN §6). STRUCTURAL Stage 2: `model: 'none'`
// means the whole decision is code and there is NO agent phase —
// the executor runs `worker.mjs` as code-work. This task ABSORBS the
// release workflow's own independent 00:30 cron: the workflow becomes push +
// workflow_dispatch only, and this task is the one place that fires its daily
// leg, so the scheduler stays the repo's only cron (DESIGN §3, decision §11.6).
//
// Self-contained (imports nothing): the whole contract is this default export.

const norm = (v) => String(v ?? '').replace(/^v/, '').trim(); // compare tags/versions modulo a leading 'v'

export default {
  id: 'store-release',
  frequency: 'daily',              // the 04:00 anchor (DESIGN §2) — replaces the workflow's own 00:30 cron
  precondition_signals: ['release', 'commits'],
  agent_model: 'none',                   // pure code — no agent (task-code-work DESIGN §4)
  expected_outcome: 'none',                 // it only TRIGGERS the gated publish workflow; publishing stays behind that workflow's own guards
  code_work: 'node worker.mjs',      // the executor runs this as code_work (cwd = this task dir) — DESIGN §3
  code_work_timeout: 120,            // the dispatch is a quick REST call; a tight bound (the await-the-run Stage 2 would widen it)

  // Detect a deployable change since the last release, entirely in code:
  //   (a) the manifest version has advanced past the latest published release
  //       (an unreleased bump — the same signal the old run_daily gate used), OR
  //   (b) a substantive default-branch commit landed in the window (a real ship).
  // Ship-path precision (the daily job's `ship_paths` filter) is NOT re-derived
  // here — .github/release.config isn't in a precondition's scope — because the
  // dispatched daily workflow does the authoritative shipped-file diff vs the
  // latest release tag and no-ops when nothing shippable moved. So the
  // precondition is the cheap pre-filter; the workflow is the exact gate.
  precondition(signals) {
    const rel = signals.release ?? {};
    const shipped = norm(rel.manifestVersion);
    const released = norm(rel.latestTag);
    const manifestAhead = shipped !== '' && shipped !== released;
    const substantive = signals.commits?.substantiveChange === true;

    if (manifestAhead) {
      return { run: true, reason: released ? `manifest ${shipped} is ahead of released ${released}` : `manifest ${shipped}, no release yet` };
    }
    if (substantive) {
      return { run: true, reason: 'substantive default-branch change in the window — let the daily release workflow diff shipped files' };
    }
    return { run: false, reason: 'manifest matches the latest release and no substantive change in the window' };
  },
};
=== WORKER ===
// store-release worker (task-code-work DESIGN §3/§4). This task is
// `agent_model: 'none'` with `code_work: 'node worker.mjs'`, so the
// scheduler runs THIS FILE as a subprocess (cwd = this task dir) bounded by
// `code_work_timeout` — there is no agent phase on
// success. Its one job is to TRIGGER the repo's vendored `Release to Chrome
// Store` orchestrator in daily mode and hand off: the orchestrator's `daily` leg
// does the authoritative shipped-file diff, patch bump, and gated submission, so
// this worker never decides what ships and never publishes anything itself.
//
// This absorbs the release workflow's retired 00:30 cron (per-project-scheduling
// decision §11.6): the scheduler is the repo's only cron, and this is the surface
// that fires the daily release.
//
// Self-contained — imports only node builtins (the pack-independence barrier
// forbids reaching into the engine). It reads its context from the CLAUDINITE_* /
// GITHUB_* env the scheduler injects and calls the Actions REST API directly over
// the injected GITHUB_TOKEN, the one sanctioned non-MCP surface (DESIGN §10). A
// non-204 dispatch, or a throw, exits non-zero — the scheduler then converges the
// task to needs-human.

import { pathToFileURL } from 'node:url';

// The vendored orchestrator's file name and the dispatch mode that runs its daily
// leg (release-workflows.mjs STUB_FILE / RELEASE.md §Workflow). Bare literals —
// this worker imports nothing from the engine, and the name is the
// conformance-pinned fingerprint.
const ORCHESTRATOR_FILE = 'chrome-extension-release.yml';
const DISPATCH_MODE = 'daily';
const API = 'https://api.github.com';

// A minimal Actions-REST call over the injected GITHUB_TOKEN. Returns { status }.
async function gh(path, { method = 'GET', body } = {}) {
  const res = await fetch(`${API}${path}`, {
    method,
    headers: {
      authorization: `Bearer ${process.env.GITHUB_TOKEN}`,
      accept: 'application/vnd.github+json',
      'x-github-api-version': '2022-11-28',
      ...(body ? { 'content-type': 'application/json' } : {}),
    },
    body: body ? JSON.stringify(body) : undefined,
  });
  return { status: res.status };
}

export async function main() {
  const repo = process.env.CLAUDINITE_REPO || process.env.GITHUB_REPOSITORY;
  const ref = process.env.CLAUDINITE_DEFAULT_BRANCH || 'main';
  const item = process.env.CLAUDINITE_ITEM || '';
  if (!repo) { console.error('store-release: no repo in env (CLAUDINITE_REPO/GITHUB_REPOSITORY)'); process.exit(1); }

